const Ledger = (() => {
  const capacity = 8;
  function localDate(d) {
    return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
  }
  function nextDay(day,time) {
    const d=new Date(), now=new Date();
    d.setDate(d.getDate()+(day-d.getDay()+7)%7);
    d.setHours(...time.split(':').map(Number),0,0);
    if(d<now) d.setDate(d.getDate()+7);
    return localDate(d);
  }
  function entry(label,delta,detail='') { return {label,delta,detail,at:new Date().toISOString()}; }
  function initial() {
    return {students:[4,2,1].map((n,i)=>({code:'P0'+(i+1),history:[entry('Opening balance',n)]})),
      workshops:[['Tuesday Handbuilding',2,'18:00'],['Saturday Glazing',6,'10:00']].map(([title,day,time],i)=>({id:'w'+i,title,date:nextDay(day,time),time,bookings:[]}))};
  }
  const balance=s=>s.history.reduce((sum,e)=>sum+e.delta,0);
  function requireThat(ok,msg){if(!ok) throw new Error(msg);}
  function change(state,action,data) {
    const {code,id,title,date,time,amount,reason}=data;
    const s=state.students.find(x=>x.code===code);
    if(action==='addWorkshop'){
      requireThat(title?.trim() && title.length<=80 && /^\d{4}-\d\d-\d\d$/.test(date) && localDate(new Date(date+'T12:00:00'))===date && /^([01]\d|2[0-3]):[0-5]\d$/.test(time),'Enter a workshop name, date and time.');
      state.workshops.push({id:crypto.randomUUID(),title:title.trim(),date,time,bookings:[]});return;
    }
    if(action==='addStudent'){
      requireThat(/^[A-Z0-9-]{1,12}$/.test(code) && !s,'Enter a unique student code using letters, numbers or hyphens.');
      requireThat(Number.isSafeInteger(amount)&&amount>=0&&amount<=9999,'Enter 0–9999 opening credits.');
      state.students.push({code,history:[entry('Opening balance',amount)]});return;
    }
    requireThat(s,'Choose a student.');
    if(action==='topup'){
      requireThat(Number.isSafeInteger(amount)&&amount>0&&amount<=9999,'Enter 1–9999 credits.');
      s.history.push(entry('Prepaid credits added',amount));return;
    }
    const w=state.workshops.find(x=>x.id===id);
    requireThat(w,'Choose a workshop.');
    const b=w.bookings.find(x=>x.code===code);
    const detail=w.title+' · '+w.date+' '+w.time;
    if(action==='reserve'){
      requireThat(!b,'This student already holds a seat.');
      requireThat(w.bookings.length<capacity,'All eight seats are taken.');
      w.bookings.push({code,status:'Reserved'});return;
    }
    requireThat(b,'This reservation has changed. Reopen the register.');
    if(action==='correct'){
      requireThat(b.status==='Attended','Attendance has already been corrected.');
      requireThat(reason?.trim(),'Give a reason for the correction.');
      b.status='Reserved';s.history.push(entry('Attendance adjustment',1,detail+' · '+reason.trim()));return;
    }
    requireThat(b.status==='Reserved','Only a reservation can be marked or cancelled.');
    if(action==='cancel'){w.bookings.splice(w.bookings.indexOf(b),1);return;}
    requireThat(action==='attend' && balance(s)>0,'Attendance requires one available credit.');
    b.status='Attended';s.history.push(entry('Attendance',-1,detail));
  }
  return {initial,balance,change,capacity};
})();

"use strict";

const icons = {
  vase: '<path d="M9 3h6m-5 0v4c0 2-5 4-5 8a7 7 0 0 0 14 0c0-4-5-6-5-8V3M6 13h12M6 17h12"/>',
  calendar: '<rect x="3.5" y="5.5" width="17" height="15" rx="2"/><path d="M7.5 3.5v4m9-4v4m-13 3h17m-12 5h2m3 0h2"/>',
  people: '<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a5 5 0 0 1 5-5h2a5 5 0 0 1 5 5v2m1-15a3 3 0 0 1 0 6m4 9v-2a5 5 0 0 0-3-4.6"/>',
  archive: '<rect x="3" y="4" width="18" height="5" rx="1"/><path d="M5 9v10a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V9m-9 4h4"/>',
  plus: '<path d="M12 5v14M5 12h14"/>',
  arrow: '<path d="M5 12h13m-5-5 5 5-5 5"/>',
  chevron: '<path d="m9 6 6 6-6 6"/>',
  close: '<path d="m6 6 12 12M18 6 6 18"/>',
  check: '<path d="m5 12 4 4 10-10"/>',
  download: '<path d="M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4"/>'
};

function icon(name) {
  return '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + icons[name] + '</svg>';
}

const content = document.querySelector("#content");
const dialog = document.querySelector("#dialog");
const notice = document.querySelector("#notice");
const storageLabel = document.querySelector("#storage-label");
const escape = value => String(value).replace(/[&<>"']/g, character => ({
  "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
})[character]);
const workshopDate = workshop => new Date(workshop.date + "T12:00:00");
const weekday = date => date.toLocaleDateString("en-US", { weekday: "long" });
const shortDate = date => date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
const fullDate = date => date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
const entryTime = date => date.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
const studentCredits = amount => amount + (amount === 1 ? " credit" : " credits");

let db;
let events;
let state;
let view = "workshops";
let selectedId;
let noticeTimer;
let returnFocus;
let saving = false;
const changes = typeof BroadcastChannel === "function" ? new BroadcastChannel("kiln-ledger:" + location.pathname) : null;

document.querySelectorAll("[data-icon]").forEach(element => {
  element.innerHTML = icon(element.dataset.icon);
});

function orderedWorkshops() {
  return [...state.workshops.values()].sort((a, b) =>
    (a.date + a.time).localeCompare(b.date + b.time) || a.title.localeCompare(b.title));
}

function orderedStudents() {
  return [...state.students.values()].sort((a, b) => a.code.localeCompare(b.code, "en", { numeric: true }));
}

function button(label, action, { style = "secondary", glyph, key = "", disabled = false } = {}) {
  return `<button type="button" class="button ${style}" data-action="${action}" data-key="${escape(key)}" ${disabled ? "disabled" : ""}>${glyph ? icon(glyph) : ""}${escape(label)}</button>`;
}

function workshopCard(workshop) {
  const date = workshopDate(workshop);
  const count = Ledger.occupied(workshop);
  const selected = workshop.id === selectedId;
  return `<button type="button" class="workshop-card${selected ? " selected" : ""}" data-action="select-workshop" data-key="${escape(workshop.id)}" aria-pressed="${selected}">
    <span class="workshop-top">
      <span class="date-tile"><span>${date.toLocaleDateString("en-US", { month: "short" })}</span><strong>${date.getDate()}</strong></span>
      <span class="workshop-summary"><strong>${escape(workshop.title)}</strong><span>${weekday(date)} · ${workshop.time}</span></span>
      <span class="workshop-arrow">${icon("chevron")}</span>
    </span>
    <span class="workshop-bottom">
      <span class="seats" aria-hidden="true">${Array.from({ length: Ledger.capacity }, (_, index) => `<span class="${index < count ? "taken" : ""}"></span>`).join("")}</span>
      <span>${count} / ${Ledger.capacity} seats filled</span>
    </span>
  </button>`;
}

function roster(workshop) {
  const active = [...workshop.bookings].filter(([, status]) => status !== "Cancelled");
  const cancelled = [...workshop.bookings].filter(([, status]) => status === "Cancelled");
  const attendees = active.filter(([, status]) => status === "Attended").length;
  const seatsLeft = Ledger.capacity - active.length;
  const canReserve = seatsLeft > 0 && [...state.students.keys()].some(code =>
    !workshop.bookings.has(code) || workshop.bookings.get(code) === "Cancelled");
  const rows = [...active, ...cancelled].map(([code, status]) => `<tr>
    <th scope="row"><button type="button" class="text-button student-link" data-action="history" data-key="${escape(code)}">${escape(code)}</button></th>
    <td><span class="status ${status.toLowerCase()}">${status}</span></td>
    <td class="row-actions">${status === "Reserved"
      ? button("Mark attended", "attend", { style: "quiet", key: code }) + button("Cancel", "cancel", { style: "quiet muted", key: code })
      : status === "Attended" ? button("Correct", "correct", { style: "quiet", key: code }) : ""}</td>
  </tr>`).join("");
  return `<section class="panel roster" aria-labelledby="roster-title">
    <div class="panel-head">
      <div><h2 id="roster-title">Workshop roster</h2><p>${escape(workshop.title)} · ${shortDate(workshopDate(workshop))}</p></div>
      ${button("Reserve seat", "reserve", { style: "primary", glyph: "plus", disabled: !canReserve })}
    </div>
    <div class="roster-stats">
      <span><i class="dot open"></i>${seatsLeft} open</span>
      <span><i class="dot reserved"></i>${active.length - attendees} reserved</span>
      <span><i class="dot attended"></i>${attendees} attended</span>
    </div>
    ${rows ? `<table class="roster-table"><thead><tr><th scope="col">Student</th><th scope="col">Status</th><th scope="col">Actions</th></tr></thead><tbody>${rows}</tbody></table>`
      : `<div class="empty"><span class="empty-icon">${icon("people")}</span><h3>No reservations yet</h3><p>Reserve a seat to add a student to the roster.</p></div>`}
    ${!canReserve && seatsLeft > 0 ? `<p class="panel-note">${state.students.size ? "All current students already have seats." : "Add a student before reserving a seat."}</p>` : ""}
  </section>`;
}

function balancePanel() {
  const students = orderedStudents();
  return `<section class="panel balances" aria-labelledby="balance-title">
    <div class="panel-head"><div><h2 id="balance-title">Credit balances</h2><p>Open a student’s balance history.</p></div></div>
    <ul class="balance-list">${students.slice(0, 5).map(student => `<li><button type="button" class="balance-button" data-action="history" data-key="${escape(student.code)}">
      <span class="student-avatar">${icon("people")}</span><strong>${escape(student.code)}</strong>
      <span class="balance-number">${studentCredits(student.balance)}</span>${icon("chevron")}
    </button></li>`).join("")}</ul>
    <div class="panel-foot">${button("All students", "students", { style: "text", glyph: "arrow" })}</div>
  </section>`;
}

function workshopsView() {
  const workshops = orderedWorkshops();
  const selected = state.workshops.get(selectedId) || workshops[0];
  if (selected) selectedId = selected.id;
  const held = workshops.reduce((total, workshop) => total + Ledger.occupied(workshop), 0);
  return `<header class="page-header">
    <div><h1>Workshops</h1><p>Manage reservations and record attendance.</p></div>
    ${button("Add workshop", "add-workshop", { style: "primary", glyph: "plus" })}
  </header>
  <section class="overview" aria-labelledby="overview-title">
    <div class="overview-art" aria-hidden="true"></div>
    <div class="overview-content">
      <h2 id="overview-title">Studio overview</h2>
      <dl><div><dt>Workshops</dt><dd>${workshops.length}</dd></div>
      <div><dt>Seats filled</dt><dd>${held}<small> / ${workshops.length * Ledger.capacity}</small></dd></div>
      <div><dt>Students</dt><dd>${state.students.size}</dd></div></dl>
    </div>
  </section>
  <section class="schedule" aria-labelledby="schedule-title">
    <div class="section-head"><h2 id="schedule-title">Workshop schedule</h2><span>8 seats per workshop</span></div>
    ${workshops.length ? `<div class="workshop-grid">${workshops.map(workshopCard).join("")}</div>` : '<p>No workshops yet.</p>'}
  </section>
  <div class="detail-grid">${selected ? roster(selected) : ""}${balancePanel()}</div>`;
}

function studentsView() {
  return `<header class="page-header">
    <div><h1>Students</h1><p>Manage prepaid visit credits and review balance history.</p></div>
    ${button("Add student", "add-student", { style: "primary", glyph: "plus" })}
  </header>
  <section class="panel directory" aria-labelledby="directory-title">
    <div class="panel-head"><div><h2 id="directory-title">Student balances</h2><p>${state.students.size} ${state.students.size === 1 ? "student" : "students"}</p></div></div>
    <table><thead><tr><th scope="col">Student</th><th scope="col">Balance</th><th scope="col">Actions</th></tr></thead><tbody>
      ${orderedStudents().map(student => `<tr><th scope="row">${escape(student.code)}</th>
        <td>${studentCredits(student.balance)}</td><td class="row-actions">
        ${button("View history", "history", { style: "quiet", key: student.code })}
        ${button("Add credits", "add-credits", { style: "quiet", key: student.code })}
        </td></tr>`).join("")}
    </tbody></table>
    ${state.students.size ? "" : '<p class="panel-note">Add a student to start tracking credits.</p>'}
  </section>`;
}

function render() {
  const focused = document.activeElement;
  const focusAction = content.contains(focused) ? focused.dataset.action : null;
  const focusKey = focusAction ? focused.dataset.key : null;
  content.innerHTML = view === "students" ? studentsView() : workshopsView();
  content.querySelector("h1").tabIndex = -1;
  document.querySelectorAll(".navigation button").forEach(item => {
    if (item.dataset.action === view) item.setAttribute("aria-current", "page");
    else item.removeAttribute("aria-current");
  });
  if (focusAction) {
    const replacement = [...content.querySelectorAll("[data-action]")].find(item =>
      item.dataset.action === focusAction && item.dataset.key === focusKey && !item.disabled);
    (replacement || content.querySelector("h1")).focus({ preventScroll: true });
  }
}

function announce(message) {
  clearTimeout(noticeTimer);
  notice.textContent = message;
  noticeTimer = setTimeout(() => { notice.textContent = ""; }, 5000);
}

function dialogFrame(title, description, body, wide = false) {
  if (!dialog.open) returnFocus = document.activeElement;
  dialog.classList.toggle("wide", wide);
  dialog.innerHTML = `<header class="dialog-head"><div><h2 id="dialog-title">${escape(title)}</h2>
    ${description ? `<p>${escape(description)}</p>` : ""}</div>
    <button class="icon-button" type="button" data-action="close" aria-label="Close">${icon("close")}</button></header>${body}`;
  if (!dialog.open) dialog.showModal();
  const focus = dialog.querySelector("[autofocus]") || dialog.querySelector("[data-action=close]");
  focus.focus();
}

function formDialog(title, description, label, fields, submit, wide = false) {
  dialogFrame(title, description, `<form class="dialog-form">${fields}<p class="form-error" role="alert" hidden></p>
    <div class="dialog-actions">${button("Cancel", "close")}<button type="submit" class="button primary">${escape(label)}</button></div></form>`, wide);
  const form = dialog.querySelector("form");
  form.addEventListener("submit", async event => {
    event.preventDefault();
    if (saving) return;
    const error = form.querySelector(".form-error");
    error.hidden = true;
    saving = true;
    form.querySelector("button[type=submit]").disabled = true;
    try {
      await submit(new FormData(form));
      dialog.close();
    } catch (problem) {
      error.textContent = problem.message;
      error.hidden = false;
    } finally {
      saving = false;
      form.querySelector("button[type=submit]").disabled = false;
    }
  });
}

async function apply(event, message, newSelection) {
  const record = { ...event, at: new Date().toISOString() };
  const updated = await Ledger.transact(db, current => {
    if (!current) throw new Error("The studio ledger could not be found. Reopen the tracker.");
    const next = [...current, record];
    Ledger.replay(next);
    return next;
  });
  if (newSelection) selectedId = newSelection;
  setEvents(updated);
  changes?.postMessage("updated");
  announce(message);
}

function setEvents(current) {
  state = Ledger.replay(current);
  events = current;
  render();
}

function showHistory(code) {
  const student = state.students.get(code);
  if (!student) return;
  const rows = student.history.slice().reverse().map(item => `<tr>
    <th scope="row"><strong>${item.label}</strong>
      ${item.workshop ? `<span class="table-detail">${escape(item.workshop.title)} · ${fullDate(workshopDate(item.workshop))}</span>` : ""}
      ${item.note ? `<span class="table-detail">${escape(item.note)}</span>` : ""}</th>
    <td><time datetime="${escape(item.at)}">${fullDate(new Date(item.at))}<span class="table-detail">${entryTime(new Date(item.at))}</span></time></td>
    <td class="number change ${item.change < 0 ? "debit" : "credit"}">${item.change > 0 ? "+" : ""}${item.change}</td>
    <td class="number">${item.balance}</td></tr>`).join("");
  dialogFrame(code + " · Balance history", studentCredits(student.balance) + " available",
    `<div class="history-table"><table><thead><tr><th scope="col">Entry</th><th scope="col">Recorded</th><th scope="col" class="number">Change</th><th scope="col" class="number">Balance</th></tr></thead><tbody>${rows}</tbody></table></div>
    <div class="dialog-actions history-actions">${button("Close", "close")}${button("Add credits", "add-credits", { style: "primary", key: code, glyph: "plus" })}</div>`, true);
}

function addWorkshop() {
  formDialog("Add workshop", "Each workshop has eight seats.", "Add workshop",
    `<label>Workshop name<input name="title" required maxlength="70" autofocus placeholder="e.g. Wheel Throwing"></label>
    <div class="form-grid"><label>Date<input name="date" type="date" required value="${Ledger.dayString(new Date())}"></label>
    <label>Start time<input name="time" type="time" required></label></div>`,
    data => {
      const id = crypto.randomUUID();
      return apply({ kind: "workshop", id, title: data.get("title").trim(), date: data.get("date"), time: data.get("time") }, "Workshop added.", id);
    });
}

function addStudent() {
  formDialog("Add student", "Use a unique code for the student.", "Add student",
    '<label>Student code<input name="code" required maxlength="16" autofocus placeholder="e.g. P04" spellcheck="false"></label><label>Opening credits<input name="amount" type="number" min="0" step="1" required value="0"></label>',
    data => {
      const code = data.get("code").trim().toUpperCase();
      return apply({ kind: "student", code, amount: Number(data.get("amount")) }, code + " added.");
    });
}

function addCredits(code) {
  const student = state.students.get(code);
  if (!student) return;
  formDialog("Add credits for " + code, studentCredits(student.balance) + " currently available", "Add credits",
    '<label>Credits to add<input name="amount" type="number" min="1" step="1" required autofocus></label><label>Note (optional)<input name="note" maxlength="200" placeholder="e.g. Prepaid visit pack"></label>',
    data => apply({ kind: "credits", code, amount: Number(data.get("amount")), note: data.get("note").trim() || undefined }, "Credits added for " + code + "."));
}

function reserve(workshop) {
  const available = orderedStudents().filter(student =>
    !workshop.bookings.has(student.code) || workshop.bookings.get(student.code) === "Cancelled");
  formDialog("Reserve a seat", workshop.title + " · " + fullDate(workshopDate(workshop)) + " · " + workshop.time, "Reserve seat",
    `<label>Student<select name="code" required autofocus><option value="">Choose a student</option>
    ${available.map(student => `<option value="${escape(student.code)}">${escape(student.code)} · ${studentCredits(student.balance)}</option>`).join("")}</select></label>
    <p class="form-hint">The student’s balance changes when you record attendance.</p>`,
    data => apply({ kind: "reserve", id: workshop.id, code: data.get("code") }, "Seat reserved for " + data.get("code") + "."));
}

function changeAttendance(action, code, workshop) {
  const student = state.students.get(code);
  if (!student) return;
  switch (action) {
    case "attend":
      formDialog("Mark " + code + " attended", workshop.title, "Mark attended",
        `<p class="form-hint">${student.balance ? "Recording attendance uses 1 visit credit." : "This student has no credits left. Add a credit before recording attendance."}</p>
        ${student.balance ? "" : button("Add credits", "add-credits", { key: code, glyph: "plus" })}`,
        () => apply({ kind: "attend", id: workshop.id, code }, "Attendance recorded for " + code + "."));
      if (student.balance === 0) dialog.querySelector("button[type=submit]").disabled = true;
      break;
    case "cancel":
      formDialog("Cancel reservation for " + code, workshop.title, "Cancel reservation",
        '<p class="form-hint">The seat will open up and the credit balance will stay the same.</p>',
        () => apply({ kind: "cancel", id: workshop.id, code }, "Reservation cancelled for " + code + "."));
      break;
    case "correct":
      formDialog("Correct attendance for " + code, workshop.title, "Save correction",
        '<p class="form-hint">This returns 1 credit and records an adjustment in the student’s history.</p><label>Corrected status<select name="status" required><option value="Reserved">Reserved · keep the seat</option><option value="Cancelled">Cancelled · release the seat</option></select></label><label>Reason<textarea name="note" rows="2" required maxlength="200" autofocus></textarea></label>',
        data => apply({ kind: "correct", id: workshop.id, code, status: data.get("status"), note: data.get("note").trim() }, "Attendance corrected for " + code + "."));
      break;
  }
}

function showBackups() {
  dialogFrame("Backups", "The ledger is stored in this browser on this device.",
    `<div class="backup-body"><p>Save a copy of your workshops, reservations and credit history. Restoring a backup replaces the current ledger.</p>
    <div class="dialog-actions">${button("Restore backup", "restore")}${button("Download backup", "download", { style: "primary", glyph: "download" })}</div></div>`);
}

async function downloadBackup() {
  const current = await Ledger.transact(db);
  const blob = new Blob([JSON.stringify({ format: "kiln-ledger", version: 1, events: current }, null, 2) + "\n"], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = "kiln-ledger-" + Ledger.dayString(new Date()) + ".json";
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  dialog.close();
  announce("Backup downloaded.");
}

function restoreBackup() {
  formDialog("Restore a backup", "This replaces all workshops, students and history in the current ledger.", "Replace ledger",
    '<label>Backup file<input name="file" type="file" accept=".json,application/json" required autofocus></label><label class="checkbox"><input name="confirm" type="checkbox" required> Replace the current ledger with this backup.</label>',
    async data => {
      let backup;
      try {
        backup = JSON.parse(await data.get("file").text());
      } catch {
        throw new Error("Choose a readable Kiln Ledger backup file.");
      }
      if (!backup || backup.format !== "kiln-ledger" || backup.version !== 1) throw new Error("Choose a Kiln Ledger backup file.");
      Ledger.replay(backup.events);
      const updated = await Ledger.transact(db, () => backup.events);
      selectedId = undefined;
      setEvents(updated);
      changes?.postMessage("updated");
      announce("Backup restored.");
    });
}

document.addEventListener("click", event => {
  const target = event.target.closest("button[data-action]");
  if (!target || !state || saving) return;
  const action = target.dataset.action;
  const key = target.dataset.key;
  const workshop = state.workshops.get(selectedId);
  switch (action) {
    case "workshops":
    case "students":
      view = action;
      render();
      content.querySelector("h1").focus();
      break;
    case "select-workshop":
      selectedId = key;
      render();
      break;
    case "add-workshop": addWorkshop(); break;
    case "add-student": addStudent(); break;
    case "history": showHistory(key); break;
    case "add-credits": addCredits(key); break;
    case "reserve": if (workshop) reserve(workshop); break;
    case "cancel":
    case "attend":
    case "correct":
      if (workshop) changeAttendance(action, key, workshop);
      break;
    case "data": showBackups(); break;
    case "download": downloadBackup().catch(problem => {
      dialogFrame("Backup unavailable", problem.message, "");
    }); break;
    case "restore": restoreBackup(); break;
    case "close": dialog.close(); break;
  }
});

dialog.addEventListener("cancel", event => { if (saving) event.preventDefault(); });
dialog.addEventListener("close", () => {
  if (returnFocus?.isConnected && !returnFocus.disabled) returnFocus.focus();
  else if (returnFocus) {
    const { action, key } = returnFocus.dataset;
    const replacement = [...content.querySelectorAll("button[data-action]")].find(item =>
      item.dataset.action === action && item.dataset.key === key && !item.disabled);
    const fallback = document.querySelector("#roster-title") || content.querySelector("h1");
    if (fallback) fallback.tabIndex = -1;
    (replacement || fallback)?.focus({ preventScroll: true });
  }
});

async function sync() {
  if (!db || !state) return;
  try {
    const latest = await Ledger.transact(db);
    if (latest && JSON.stringify(latest) !== JSON.stringify(events)) setEvents(latest);
  } catch (problem) {
    announce(problem.message);
  }
}

if (changes) changes.onmessage = sync;
window.addEventListener("focus", sync);

(async () => {
  try {
    db = await Ledger.open();
    const initial = await Ledger.transact(db, current => current ?? Ledger.initialEvents());
    selectedId = "handbuilding";
    setEvents(initial);
    storageLabel.innerHTML = "<span></span>Stored on this device";
    storageLabel.classList.add("ready");
  } catch (problem) {
    content.innerHTML = `<h1>Ledger unavailable</h1><p>${escape(problem.message)}</p><p>Open this file in a regular browser window with local storage enabled.</p>`;
    storageLabel.innerHTML = "<span></span>Storage unavailable";
    document.querySelectorAll(".sidebar button").forEach(item => { item.disabled = true; });
  } finally {
    content.setAttribute("aria-busy", "false");
  }
})();

"use strict";

const Ledger = (() => {
  const capacity = 8;
  const storageName = "kiln-ledger";
  const storageKey = location.pathname;

  function fail(message) {
    throw new Error(message);
  }

  function dayString(date) {
    const pad = value => String(value).padStart(2, "0");
    return [date.getFullYear(), pad(date.getMonth() + 1), pad(date.getDate())].join("-");
  }

  function initialEvents(now = new Date()) {
    const tuesday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12);
    const days = (2 - tuesday.getDay() + 7) % 7;
    tuesday.setDate(tuesday.getDate() + (days || (now.getHours() >= 18 ? 7 : 0)));
    const saturday = new Date(tuesday);
    saturday.setDate(saturday.getDate() + 4);
    const at = now.toISOString();
    return [
      { kind: "student", code: "P01", amount: 4, at },
      { kind: "student", code: "P02", amount: 2, at },
      { kind: "student", code: "P03", amount: 1, at },
      { kind: "workshop", id: "handbuilding", title: "Tuesday Handbuilding", date: dayString(tuesday), time: "18:00", at },
      { kind: "workshop", id: "glazing", title: "Saturday Glazing", date: dayString(saturday), time: "10:00", at }
    ];
  }

  function occupied(workshop) {
    return [...workshop.bookings.values()].filter(status => status !== "Cancelled").length;
  }

  function entry(student, event, change, label, workshop) {
    const balance = student.balance + change;
    if (!Number.isSafeInteger(balance) || balance < 0) fail("The credit balance would be out of range.");
    student.balance = balance;
    student.history.push({ at: event.at, label, change, balance, workshop,
      note: event.kind === "credits" || event.kind === "correct" ? event.note : undefined });
  }

  function validText(value, maximum) {
    return typeof value === "string" && value.trim().length > 0 && value.length <= maximum;
  }

  function validDate(value) {
    if (typeof value !== "string" || !/^\d{4}-\d\d-\d\d$/.test(value) || value.startsWith("0000")) return false;
    const parsed = new Date(value + "T00:00:00Z");
    return Number.isFinite(+parsed) && parsed.toISOString().slice(0, 10) === value;
  }

  function replay(events) {
    if (!Array.isArray(events) || !events.length) fail("The backup has no studio records.");
    const students = new Map();
    const workshops = new Map();
    for (const event of events) {
      if (!event || typeof event.at !== "string" || !Number.isFinite(Date.parse(event.at))) {
        fail("A studio record has an invalid timestamp.");
      }
      const student = students.get(event.code);
      const workshop = workshops.get(event.id);
      switch (event.kind) {
        case "student": {
          if (typeof event.code !== "string" || !/^[A-Z0-9][A-Z0-9-]{0,15}$/.test(event.code)) {
            fail("Use 1–16 letters, numbers or hyphens for a student code.");
          }
          if (student) fail("That student code already exists.");
          if (!Number.isSafeInteger(event.amount) || event.amount < 0) fail("Enter a valid opening balance.");
          const record = { code: event.code, balance: 0, history: [] };
          entry(record, event, event.amount, "Opening balance");
          students.set(event.code, record);
          break;
        }
        case "workshop":
          if (!validText(event.id, 100) || workshop || !validText(event.title, 70) || !validDate(event.date) ||
            typeof event.time !== "string" || !/^([01]\d|2[0-3]):[0-5]\d$/.test(event.time)) {
            fail("Enter a workshop name, a valid date and a start time.");
          }
          workshops.set(event.id, { id: event.id, title: event.title, date: event.date, time: event.time, bookings: new Map() });
          break;
        case "credits":
          if (!student) fail("That student could not be found.");
          if (!Number.isSafeInteger(event.amount) || event.amount < 1) fail("Enter a whole number of credits greater than zero.");
          if (event.note !== undefined && !validText(event.note, 200)) fail("Enter a valid credit note.");
          entry(student, event, event.amount, "Credits added");
          break;
        case "reserve":
        case "cancel":
        case "attend":
        case "correct": {
          if (!student || !workshop) fail("The student or workshop could not be found.");
          const status = workshop.bookings.get(event.code);
          if (event.kind === "reserve") {
            if (status && status !== "Cancelled") fail("This student already has a seat in this workshop.");
            if (occupied(workshop) >= capacity) fail("This workshop is full.");
            workshop.bookings.set(event.code, "Reserved");
          } else if (event.kind === "cancel") {
            if (status !== "Reserved") fail("Only a reservation can be cancelled.");
            workshop.bookings.set(event.code, "Cancelled");
          } else if (event.kind === "attend") {
            if (status !== "Reserved") fail("A reservation is required to record attendance.");
            if (student.balance < 1) fail("This student has no credits left. Add a credit before recording attendance.");
            entry(student, event, -1, "Attendance", workshop);
            workshop.bookings.set(event.code, "Attended");
          } else {
            if (status !== "Attended") fail("Only recorded attendance can be corrected.");
            if (!["Reserved", "Cancelled"].includes(event.status)) fail("Choose a corrected status.");
            if (!validText(event.note, 200)) fail("Enter a reason for the correction.");
            entry(student, event, 1, "Attendance correction", workshop);
            workshop.bookings.set(event.code, event.status);
          }
          break;
        }
        default:
          fail("The ledger contains an unknown record type.");
      }
    }
    return { students, workshops };
  }

  function open() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(storageName, 1);
      request.onupgradeneeded = () => request.result.createObjectStore("studios");
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(new Error("Local storage could not be opened."));
      request.onblocked = () => reject(new Error("Close other copies of the tracker and reopen this page."));
    });
  }

  // Recheck each change inside a read/write transaction so concurrent tabs share the same rules.
  function transact(db, update) {
    return new Promise((resolve, reject) => {
      const transaction = db.transaction("studios", update ? "readwrite" : "readonly");
      const records = transaction.objectStore("studios");
      const request = records.get(storageKey);
      let result;
      let error;
      request.onsuccess = () => {
        try {
          result = update ? update(request.result) : request.result;
          if (update && result !== request.result) records.put(result, storageKey);
        } catch (problem) {
          error = problem;
          transaction.abort();
        }
      };
      transaction.oncomplete = () => resolve(result);
      transaction.onabort = () => reject(error || new Error("Local storage could not finish the change."));
    });
  }

  return { capacity, dayString, initialEvents, occupied, open, replay, transact };
})();

:root {
  color-scheme: light;
  --paper: #f7f4ee;
  --surface: #fffcf7;
  --ink: #2e2520;
  --muted: #675c55;
  --line: #e5dcd1;
  --accent: #8b422f;
  --accent-dark: #6e3222;
  --accent-tint: #f5e7dd;
  --sage: #385843;
  --sage-tint: #e7eee4;
  --amber: #79521e;
  --amber-tint: #f4ebd9;
  --sidebar: #2c2420;
  --sidebar-ink: #fbf4e9;
  --sidebar-muted: #c9b9ac;
  --sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --serif: Georgia, "Times New Roman", serif;
  --radius: 16px;
}
*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; color: var(--ink); background: var(--paper); font: 15px/1.5 var(--sans); }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; color: inherit; }
button:disabled { cursor: default; opacity: .53; }
button, a, input, select, textarea { -webkit-tap-highlight-color: transparent; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.sidebar :focus-visible { outline-color: #ffc5a9; }
button:focus:not(:focus-visible), h1:focus, h2:focus { outline: none; }
h1, h2, h3, p, dl, dd { margin: 0; }
h1, h2 { font-family: var(--serif); font-weight: 400; }
svg { display: block; flex-shrink: 0; }
[hidden] { display: none !important; }
.skip { position: fixed; top: -100px; left: 12px; z-index: 5; background: var(--surface); padding: 12px; color: var(--ink); }
.skip:focus { top: 12px; }

.shell { display: grid; grid-template-columns: 224px minmax(0, 1fr); min-height: 100vh; }
.sidebar { display: flex; flex-direction: column; position: sticky; top: 0; height: 100vh; padding: 35px 17px 24px; background: var(--sidebar); color: var(--sidebar-ink); }
.brand { display: flex; gap: 11px; align-items: center; padding: 0 8px; }
.brand-mark { display: grid; place-items: center; width: 43px; height: 43px; border-radius: 13px; color: #ffd6c1; background: #764234; }
.brand-mark svg { width: 25px; height: 25px; }
.brand-name { font: 23px/1.1 var(--serif); white-space: nowrap; }
.brand-subtitle { margin-top: 4px; color: var(--sidebar-muted); font-size: 12px; }
.navigation { display: grid; gap: 6px; margin-top: 50px; }
.sidebar button { display: flex; align-items: center; gap: 11px; min-height: 46px; width: 100%; padding: 8px 11px; text-align: left; border: 1px solid transparent; border-radius: 10px; color: var(--sidebar-muted); background: transparent; font-size: 14px; font-weight: 600; }
.sidebar button svg { width: 19px; height: 19px; }
.sidebar button:hover, .sidebar button[aria-current="page"] { color: var(--sidebar-ink); background: #49372f; }
.sidebar button[aria-current="page"] { border-color: #60463a; }
.sidebar button[aria-current="page"] svg { color: #f4b799; }
.sidebar-footer { margin-top: auto; }
.storage-label { display: flex; align-items: center; gap: 8px; margin: 13px 10px 0; padding-top: 16px; border-top: 1px solid #594940; color: var(--sidebar-muted); font-size: 12px; }
.storage-label span { width: 7px; height: 7px; border-radius: 50%; background: #e6b991; }
.storage-label.ready span { background: #aac59e; }

main { width: min(100%, 1440px); margin: 0 auto; padding: 40px clamp(24px, 4.3vw, 68px) 52px; }
.page-header { display: flex; justify-content: space-between; align-items: center; gap: 20px; margin-bottom: 25px; }
.page-header h1, #content > h1 { font-size: clamp(39px, 4.15vw, 62px); line-height: 1.03; letter-spacing: -.05em; }
.page-header p { margin-top: 8px; font-size: 15px; color: var(--muted); }
.button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-height: 44px; padding: 8px 14px; border: 1px solid transparent; border-radius: 9px; white-space: nowrap; font-size: 13px; font-weight: 650; transition: background-color .15s, border-color .15s; }
.button svg { width: 17px; height: 17px; }
.primary { color: #fffaf3; background: var(--accent); }
.primary:hover:not(:disabled), .primary:active:not(:disabled) { background: var(--accent-dark); }
.secondary { color: var(--ink); background: var(--surface); border-color: #ccbbad; }
.secondary:hover:not(:disabled), .secondary:active:not(:disabled) { background: var(--paper); border-color: var(--accent); }
.quiet { color: var(--accent-dark); background: var(--accent-tint); }
.quiet:hover, .quiet:active { background: #ead4c5; }
.quiet.muted { background: transparent; color: var(--muted); }
.quiet.muted:hover, .text:hover, .text:active { background: var(--accent-tint); }
.text, .text-button { color: var(--accent-dark); background: transparent; }
.text svg { order: 2; }
.text-button { border: 0; border-radius: 5px; min-height: 44px; padding: 0 3px; font-weight: 700; text-decoration: underline; text-underline-offset: 3px; }

.overview { position: relative; isolation: isolate; overflow: hidden; border-radius: var(--radius); padding: 22px 26px; color: #fff8ed; background: #884635; }
.overview-content { position: relative; }
.overview h2 { font-size: 24px; margin-bottom: 10px; }
.overview dl { display: flex; flex-wrap: wrap; gap: 12px 0; }
.overview dl > div { display: flex; flex-direction: column-reverse; min-width: 136px; padding: 0 24px; border-left: 1px solid #c78671; }
.overview dl > div:first-child { padding-left: 0; border-left: none; min-width: 116px; }
.overview dt { font-size: 13px; color: #ffe2d2; }
.overview dd { font: 36px/1.1 var(--serif); letter-spacing: -.035em; }
.overview dd small { font: 19px/1.1 var(--serif); color: #ffe2d2; }
.overview-art { position: absolute; width: 475px; height: 295px; right: -92px; top: -30px; opacity: .55; border-radius: 52% 43% 50% 47%; transform: rotate(-18deg); background: repeating-radial-gradient(ellipse at 49% 52%, transparent 0 11px, #d28d72 11px 12px, transparent 12px 18px); mask-image: linear-gradient(to right, transparent, black 30%); }

.schedule { margin-top: 25px; }
.section-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.section-head h2, .panel h2 { font-size: 26px; line-height: 1.18; letter-spacing: -.032em; }
.section-head > span { font-size: 13px; color: var(--muted); }
.workshop-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.workshop-card { display: flex; flex-direction: column; justify-content: space-between; gap: 14px; min-width: 0; padding: 14px; border: 1px solid var(--line); border-radius: 13px; text-align: left; background: var(--surface); transition: background-color .15s, border-color .15s; }
.workshop-card:hover { border-color: #b9856e; background: #fdf5eb; }
.workshop-card.selected { border-color: #a96247; background: #fcf1e7; box-shadow: inset 0 0 0 1px #a96247; }
.workshop-top { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 12px; width: 100%; }
.date-tile { display: grid; place-content: center; width: 52px; height: 52px; border-radius: 9px; text-align: center; color: var(--sage); background: var(--sage-tint); }
.date-tile span { font-size: 10px; font-weight: 750; text-transform: uppercase; letter-spacing: .065em; }
.date-tile strong { font: 25px/1 var(--serif); }
.selected .date-tile { background: #f0d4c3; color: var(--accent-dark); }
.workshop-summary { display: grid; gap: 3px; overflow-wrap: anywhere; }
.workshop-summary > strong { font-size: 15px; line-height: 1.22; }
.workshop-summary > span, .workshop-bottom { color: var(--muted); font-size: 12px; }
.workshop-arrow svg { width: 17px; height: 17px; color: var(--muted); }
.workshop-bottom { display: flex; flex-wrap: wrap; gap: 7px 11px; align-items: center; padding-top: 10px; border-top: 1px solid var(--line); width: 100%; }
.seats { display: flex; gap: 5px; }
.seats span { width: 13px; height: 6px; border-radius: 6px; background: #ded2c5; }
.seats .taken { background: var(--accent); }

.detail-grid { display: grid; grid-template-columns: minmax(0, 1.65fr) minmax(250px, 1fr); align-items: start; gap: 14px; margin-top: 23px; }
.panel { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); min-width: 0; }
.panel-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px 12px; padding: 17px 17px 13px; }
.panel-head h2 { overflow-wrap: anywhere; }
.panel-head p { color: var(--muted); margin-top: 4px; font-size: 13px; overflow-wrap: anywhere; }
.roster-stats { display: flex; flex-wrap: wrap; gap: 8px 15px; padding: 10px 17px; border-block: 1px solid var(--line); color: var(--muted); font-size: 12px; background: #fbf7f0; }
.roster-stats span { display: flex; align-items: center; gap: 6px; }
.dot { width: 7px; height: 7px; border-radius: 50%; background: #978275; }
.dot.reserved { background: #a36b31; }
.dot.attended { background: #58816a; }
.empty { text-align: center; padding: 22px 12px 26px; }
.empty-icon { display: grid; place-items: center; margin: 0 auto 7px; width: 40px; height: 40px; border-radius: 50%; background: var(--accent-tint); color: var(--accent-dark); }
.empty-icon svg { width: 19px; height: 19px; }
.empty h3 { font-size: 14px; }
.empty p, .panel-note { color: var(--muted); font-size: 13px; }
.panel-note { padding: 10px 17px; }
.balance-list { list-style: none; padding: 0; margin: 0 16px; }
.balance-list li { border-top: 1px solid var(--line); }
.balance-button { display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; align-items: center; gap: 8px; width: 100%; min-height: 49px; padding: 4px 3px; border: none; border-radius: 6px; background: transparent; text-align: left; }
.balance-button:hover, .balance-button:active { background: var(--paper); }
.balance-button strong { font-size: 13px; overflow-wrap: anywhere; }
.student-avatar { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; background: var(--sage-tint); color: var(--sage); }
.student-avatar svg { width: 15px; height: 15px; }
.balance-button > svg { width: 14px; height: 14px; color: var(--muted); }
.balance-number { white-space: nowrap; color: var(--sage); font-size: 12px; font-weight: 700; }
.panel-foot { border-top: 1px solid var(--line); padding: 2px 8px; }

table { border-collapse: collapse; width: 100%; font-size: 13px; }
th, td { padding: 8px 16px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: middle; overflow-wrap: anywhere; }
thead th { background: var(--paper); color: var(--muted); font-size: 11px; }
tbody tr:last-child > * { border-bottom: 0; }
.row-actions { text-align: right; }
.row-actions .button { margin: 2px; }
.roster-table th:last-child, .directory th:last-child { text-align: right; }
.status { display: inline-block; padding: 3px 8px; border-radius: 20px; font-size: 12px; font-weight: 650; }
.status.reserved { color: var(--amber); background: var(--amber-tint); }
.status.attended { color: var(--sage); background: var(--sage-tint); }
.status.cancelled { color: var(--muted); background: var(--paper); }

dialog { color: var(--ink); background: var(--surface); width: min(480px, calc(100% - 30px)); max-height: calc(100% - 28px); padding: 0; border: 1px solid var(--line); border-radius: var(--radius); box-shadow: 0 16px 60px #2c242049; }
dialog.wide { width: min(670px, calc(100% - 30px)); }
dialog::backdrop { background: #261a16a0; }
.dialog-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; padding: 19px 20px 16px; border-bottom: 1px solid var(--line); }
.dialog-head h2 { font-size: 28px; line-height: 1.15; letter-spacing: -.035em; overflow-wrap: anywhere; }
.dialog-head p { margin-top: 5px; color: var(--muted); font-size: 13px; overflow-wrap: anywhere; }
.icon-button { display: grid; place-items: center; flex: 0 0 44px; min-height: 44px; border: none; border-radius: 9px; background: var(--paper); }
.icon-button svg { width: 18px; height: 18px; }
.icon-button:hover { background: var(--accent-tint); }
.dialog-form, .backup-body { padding: 18px 20px 20px; }
.dialog-form { display: grid; gap: 13px; }
.dialog-form label { display: grid; gap: 5px; color: var(--ink); font-size: 13px; font-weight: 700; min-width: 0; }
input, select, textarea { min-width: 0; width: 100%; min-height: 44px; padding: 8px 10px; border: 1px solid #beaca0; border-radius: 8px; background: var(--surface); color: var(--ink); font-size: 16px; font-weight: 400; }
textarea { resize: vertical; }
input[type="file"] { font-size: 13px; }
input[type="checkbox"] { min-height: 20px; width: 20px; accent-color: var(--accent); }
.dialog-form .checkbox { display: flex; min-height: 44px; align-items: center; gap: 8px; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.form-hint { color: var(--muted); font-size: 14px; }
.form-error { color: var(--accent-dark); background: var(--accent-tint); border-radius: 8px; padding: 9px 11px; font-size: 13px; }
.dialog-actions { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: 8px; margin-top: 5px; }
.backup-body .dialog-actions { margin-top: 16px; }
.history-actions { padding: 12px 16px; border-top: 1px solid var(--line); margin-top: 0; }
.history-table th, .history-table td { vertical-align: top; }
.history-table tbody th { font-weight: 400; }
.table-detail { display: block; color: var(--muted); margin-top: 2px; }
.number { text-align: right; font-variant-numeric: tabular-nums; }
.change { font-weight: 700; }
.change.debit { color: var(--accent-dark); }
.change.credit { color: var(--sage); }
#notice:not(:empty) { position: fixed; z-index: 2; right: 18px; bottom: 18px; max-width: calc(100% - 36px); padding: 12px 16px; border-radius: 10px; background: var(--sidebar); color: var(--sidebar-ink); box-shadow: 0 3px 18px #2c242035; }

@media (max-width: 1080px) {
  .shell { grid-template-columns: 185px minmax(0, 1fr); }
  .sidebar { padding-inline: 12px; }
  main { padding-inline: 26px; }
  .detail-grid { grid-template-columns: minmax(0, 1.45fr) minmax(220px, 1fr); }
  .panel-head { padding-inline: 13px; }
  th, td { padding-inline: 9px; }
}
@media (max-width: 850px) {
  .detail-grid { grid-template-columns: 1fr; }
}
@media (max-width: 680px) {
  .shell { display: block; }
  .sidebar { position: static; height: auto; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; padding: 13px 15px 8px; }
  .brand { padding: 0; }
  .brand-mark { width: 35px; height: 35px; border-radius: 9px; }
  .brand-mark svg { width: 22px; height: 22px; }
  .brand-name { font-size: 21px; }
  .brand-subtitle { margin-top: 1px; }
  .navigation { display: flex; grid-row: 2; grid-column: 1 / -1; margin-top: 0; }
  .navigation button { width: auto; }
  .sidebar-footer { margin: 0; }
  .storage-label { display: none; }
  main { padding: 24px 15px 36px; }
  .page-header { gap: 10px; align-items: flex-start; }
  .page-header h1 { font-size: 40px; }
  .page-header .button { margin-top: 2px; padding-inline: 9px; }
  .page-header p { font-size: 13px; }
  .overview { padding: 17px; }
  .overview dl > div { min-width: 0; padding-inline: 13px; }
  .overview dl > div:first-child { min-width: 0; }
  .overview dd { font-size: 29px; }
  .overview-art { right: -245px; opacity: .4; }
}
@media (max-width: 460px) {
  .workshop-grid { grid-template-columns: 1fr; }
  .section-head h2, .panel h2 { font-size: 23px; }
  .section-head > span { font-size: 11px; }
  .history-table th, .history-table td { padding-inline: 5px; }
  .history-table table { font-size: 12px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}
